-- Nexmark qhop on clink, BLACKHOLE sink variant. NOT a nexmark query. Bids
-- per auction per 10s window sliding every 2s, so each bid lands in five
-- overlapping panes. HOP's only nexmark query is q5, whose top-1 rank makes
-- it a changelog the row-count gate cannot carry. NOTE the argument orders
-- differ and are NOT interchangeable: clink is HOP(time, SIZE, SLIDE),
-- Flink's table function is HOP(TABLE, DESCRIPTOR, SLIDE, SIZE).
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (auction BIGINT, bidder BIGINT, price BIGINT, channel VARCHAR, url VARCHAR, datetime BIGINT)
  WITH (connector='kafka', format='json', brokers='__BROKERS__', topic='nx-bid',
        group_id='clink-qhopbh-bid', auto_offset_reset='earliest',
        event_time_column='datetime', watermark_lag_ms='4001');
CREATE TABLE sink_qhop (auction BIGINT, num BIGINT) WITH (connector='blackhole');
INSERT INTO sink_qhop
SELECT auction, COUNT(*) AS num FROM bid GROUP BY HOP(datetime, INTERVAL '10' SECOND, INTERVAL '2' SECOND), auction;
